import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { ACTIVE_CSS_BUNDLE_OUTPUT, activeCssSourcePaths, compileActiveCssBundle } from './lib/active-css-bundle.mjs';

const root=new URL('../',import.meta.url);
const expected=await compileActiveCssBundle();
let actual='';
try{actual=await readFile(new URL(ACTIVE_CSS_BUNDLE_OUTPUT,root),'utf8')}catch{console.error('ACTIVE CSS VERIFICATION: FAIL\n - generated bundle is missing; run npm run prepare:css');process.exit(1)}
if(actual!==expected){
  console.error('ACTIVE CSS VERIFICATION: FAIL');
  console.error(' - generated bundle differs from the exact ordered compatibility sources');
  process.exit(1);
}
const hash=createHash('sha256').update(actual).digest('hex');
console.log('ACTIVE CSS VERIFICATION: PASS');
console.log(` - ${activeCssSourcePaths().length} additive source layers concatenate without semantic at-rule hazards`);
console.log(` - generated bytes exactly match compiler output · sha256 ${hash}`);
console.log(' - no selector, declaration, media rule or source ordering is transformed');
